import React, { useRef, useEffect } from 'react';

const BoundingBoxCanvas = ({ imageUrl, boxes }) => {
  const canvasRef = useRef(null);
  const labelColors = {
    'acne_scars': '#FF6F61',        // Coral
    'comedone': '#6B5B95',          // Purple
    'conglobata': '#88B04B',        // Green
    'crystanlline': '#F7CAC9',      // Pink
    'cystic': '#92A8D1',            // Light Blue
    'flat_wart': '#955251',         // Brown
    'folliculitis': '#B565A7',      // Lavender
    'keloid': '#009B77',            // Teal
    'milium': '#DD4124',            // Red
    'papule': '#45B8AC',            // Turquoise
    'pustule': '#EFC050',           // Yellow
    'sebo-crystan-conglo': '#5B5EA6', // Indigo
    'syringoma': '#9B2335',         // Burgundy
    'birthmark': '#BC243C'          // Maroon
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    const image = new Image();
    console.log(image);
    image.onload = () => {
      console.log('Image loaded');
      // Set canvas size to match the image
      canvas.width = 640;
      canvas.height = 640;

      // Draw the image
      context.drawImage(image, 0, 0, 640, 640);

      // Draw the bounding boxes
      boxes.forEach(box => {
        const { x_min, y_min, x_max, y_max, class_name, confidence } = box;
        const width = x_max - x_min;
        const height = y_max - y_min;        

        // Optionally, draw the class name and confidence
        if (labelColors[class_name]) {
          context.fillStyle = labelColors[class_name];
          context.strokeStyle = labelColors[class_name];
        }

        context.lineWidth = 2;
        context.strokeRect(x_min, y_min, width, height);
        context.font = '14px Arial';
        context.fillText(`${class_name} ${Number(confidence.toFixed(2))}`, x_min, y_min - 5);
      });
    };

    image.src = imageUrl;
  }, [imageUrl, boxes]);
    return <canvas ref={canvasRef} />;
};

export default BoundingBoxCanvas;
